function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  const dialogRef = useFocusTrap<HTMLElement>(onClose);
  return <div className="bf-modal-backdrop" role="presentation" onMouseDown={onClose}><section ref={dialogRef} tabIndex={-1} className="bf-modal" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(event) => event.stopPropagation()}><header><div><p className="bf-kicker">ÎNREGISTRARE RAPIDĂ</p><h2>{title}</h2></div><button className="bf-icon-button" aria-label="Închide" onClick={onClose}><X size={19} /></button></header>{children}</section></div>;
}

function ThemePicker({ theme, schedule, scheduleTimes, highContrast, background, onChange, onScheduleChange, onScheduleTimesChange, onContrastChange, onBackgroundChange, onClose }: { theme: ThemeId; schedule: ThemeSchedule; scheduleTimes: ThemeScheduleTimes; highContrast: boolean; background: BackgroundId; onChange: (theme: ThemeId) => void; onScheduleChange: (schedule: ThemeSchedule) => void; onScheduleTimesChange: (times: ThemeScheduleTimes) => void; onContrastChange: (active: boolean) => void; onBackgroundChange: (background: BackgroundId) => void; onClose: () => void }) {
  const [preview, setPreview] = useState<ThemeId>(theme);
  const [previewBackground, setPreviewBackground] = useState<BackgroundId>(background);
  const previewOption = themeOptions.find((option) => option.id === preview) || themeOptions[0];
  const scheduleIsValid = timeToMinutes(scheduleTimes.dayStart, -1) < timeToMinutes(scheduleTimes.eveningStart, -1) && timeToMinutes(scheduleTimes.eveningStart, -1) < timeToMinutes(scheduleTimes.nightStart, -1);
  const applyPreview = () => { onChange(preview); onBackgroundChange(previewBackground); onScheduleChange(schedule); onClose(); };
  const dialogRef = useFocusTrap<HTMLElement>(onClose);
  return <div className="bf-modal-backdrop bf-theme-backdrop" role="presentation" onMouseDown={onClose}><section ref={dialogRef} tabIndex={-1} className="bf-modal bf-theme-picker" role="dialog" aria-modal="true" aria-label="Alege aspectul" onMouseDown={(event) => event.stopPropagation()}><header><div><p className="bf-kicker">ASPECTUL APLICAȚIEI</p><h2>Alege o atmosferă, nu doar o culoare.</h2></div><button className="bf-icon-button" aria-label="Închide alegerea temei" onClick={onClose}><X size={19} /></button></header><p className="bf-theme-picker-intro">Previzualizezi înainte de aplicare. Verdele rămâne progres, mierea înseamnă revizuire, iar coralul atrage atenția.</p><section className={`bf-theme-preview ${preview} background-preview-${previewBackground}`} aria-label={`Previzualizare ${previewOption.name}`}><div className="bf-theme-preview-top"><span>{previewOption.mood}</span><b>{previewOption.name}</b></div><div className="bf-theme-preview-value"><small>BANI NEREPARTIZAȚI</small><strong>1.480 RON</strong><i /></div><div className="bf-theme-preview-stats"><span>DISPONIBIL <b>4.830 RON</b></span><span>REZERVAT <b>780 RON</b></span></div><div className="bf-theme-preview-nav"><i /><i /><i /><i /></div></section><p className="bf-theme-preview-note">Aceasta este o previzualizare mare a suprafețelor, cifrelor și navigației; datele tale nu se schimbă până la aplicare.</p><div className="bf-theme-grid">{themeOptions.map((option) => <button key={option.id} className={`bf-theme-option ${option.id} ${preview === option.id ? "selected" : ""}`} aria-pressed={preview === option.id} onClick={() => setPreview(option.id)}><span className="bf-theme-swatch" aria-hidden="true"><span /></span><span><em>{option.mood}</em><b>{option.name}</b><small>{option.detail}</small></span><i>{preview === option.id && <Check size={14} />}</i></button>)}</div><section className="bf-background-preferences" aria-labelledby="bf-background-title"><div><p className="bf-kicker">FUNDAL</p><h3 id="bf-background-title">Alege textura suprafeței</h3><p>Schimbă atmosfera fără să afectezi lizibilitatea datelor.</p></div><div className="bf-background-grid">{backgroundOptions.map((option) => <button key={option.id} className={previewBackground === option.id ? "selected" : ""} aria-pressed={previewBackground === option.id} onClick={() => setPreviewBackground(option.id)}><span className={`bf-background-swatch ${option.id}`} aria-hidden="true" /><b>{option.name}</b><small>{option.detail}</small></button>)}</div></section><section className="bf-theme-preferences" aria-label="Preferințe temă"><button className={schedule === "auto" ? "active" : ""} role="switch" aria-checked={schedule === "auto"} onClick={() => onScheduleChange(schedule === "auto" ? "manual" : "auto")}><span><b>Comută automat zi/noapte</b><small>{schedule === "auto" ? `Activ acum: ${themeOptions.find((item) => item.id === automaticTheme(currentLocalMinutes(), scheduleTimes))?.name || "tema automată"}. Zi ${scheduleTimes.dayStart}–${scheduleTimes.eveningStart} · seară ${scheduleTimes.eveningStart}–${scheduleTimes.nightStart} · noapte ${scheduleTimes.nightStart}–${scheduleTimes.dayStart}.` : "Folosește Porcelain ziua, Aurora seara și Ultraviolet noaptea."}</small></span><i aria-hidden="true" /></button><div className="bf-theme-schedule-fields" aria-label="Intervale automate"><label><span>Ziua începe</span><input type="time" value={scheduleTimes.dayStart} onChange={(event) => onScheduleTimesChange({ ...scheduleTimes, dayStart: event.target.value })} /></label><label><span>Seara începe</span><input type="time" value={scheduleTimes.eveningStart} onChange={(event) => onScheduleTimesChange({ ...scheduleTimes, eveningStart: event.target.value })} /></label><label><span>Noaptea începe</span><input type="time" value={scheduleTimes.nightStart} onChange={(event) => onScheduleTimesChange({ ...scheduleTimes, nightStart: event.target.value })} /></label></div>{!scheduleIsValid && <small className="bf-theme-schedule-error">Ordinea trebuie să fie zi → seară → noapte. Până la corectare se folosesc temporar valorile standard: 06:00, 17:00 și 21:00.</small>}<button className={highContrast ? "active" : ""} role="switch" aria-checked={highContrast} onClick={() => onContrastChange(!highContrast)}><span><b>Contrast extra-ridicat</b><small>Contururi, texte secundare și stări active mai puternice, fără a schimba culorile banilor.</small></span><i aria-hidden="true" /></button></section><button className="bf-theme-apply" onClick={applyPreview}><Check size={17} /> Aplică {previewOption.name}</button></section></div>;
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="bf-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

/** Previzualizare locală a bonului: bloburile rămân IndexedDB și adresa temporară este revocată la ieșire. */
function ReceiptThumbnail({ receipt }: { receipt: Receipt }) {
  const [url, setUrl] = useState<string | undefined>(receipt.imageData);
  useEffect(() => {
    if (receipt.imageData) { setUrl(receipt.imageData); return; }
    const key = receipt.imageKeys?.[0]; if (!key) { setUrl(undefined); return; }
    let active = true; let objectUrl: string | undefined;
    void receiptImageUrl(key).then((next) => { if (!active) { if (next) URL.revokeObjectURL(next); return; } objectUrl = next; setUrl(next); }).catch(() => { if (active) setUrl(undefined); });
    return () => { active = false; if (objectUrl) URL.revokeObjectURL(objectUrl); };
  }, [receipt.imageData, receipt.imageKeys?.[0]]);
  return url ? <img src={url} alt={`Bon ${receipt.vendor}`} /> : <span className="bf-receipt-icon"><ReceiptText size={21} /></span>;
}

function TransactionForm({ data, initial, onSave, onClose }: { data: AppData; initial?: Transaction; onSave: (item: Transaction) => void; onClose: () => void }) {
  const [kind, setKind] = useState<TransactionKind>(initial?.kind || "expense");
  const [title, setTitle] = useState(initial?.title || "");
  const [amount, setAmount] = useState(initial ? String(initial.amount) : "");
  const [date, setDate] = useState(initial?.date || isoToday());
  const [memberId, setMemberId] = useState(initial?.memberId || data.settings.members.find((member) => member.name === initial?.person)?.id || data.settings.members[0]?.id || "");
  const [sourceId, setSourceId] = useState(initial?.sourceId || data.settings.paymentSources.find((source) => source.name === initial?.source)?.id || data.settings.paymentSources[0]?.id || "");
  const [category, setCategory] = useState(initial?.category || "Alimente");
  const [allocationId, setAllocationId] = useState(initial?.allocationId || "outside");
  const [allocationChoiceTouched, setAllocationChoiceTouched] = useState(Boolean(initial));
  const [note, setNote] = useState(initial?.note || "");
  const [error, setError] = useState(""); const envelopeCandidates = kind === "expense" ? matchingAllocationsForExpense(data, { category, memberId, sourceId }) : []; const envelopeCandidateIds = envelopeCandidates.map((item) => item.id).join("|"); const matchedEnvelope = allocationId === "outside" ? undefined : envelopeCandidates.find((allocation) => allocation.id === allocationId); const sourceOwner = (source: AppData["settings"]["paymentSources"][number]) => data.settings.members.find((member) => member.id === source.memberId)?.name || "Comun"; const allocationMember = matchedEnvelope ? data.settings.members.find((member) => member.id === matchedEnvelope.memberId)?.name || "Familie / comun" : ""; const editedAlreadyInEnvelope = Boolean(matchedEnvelope && initial?.id && initial.allocationId === matchedEnvelope.id); const envelopeSpent = matchedEnvelope ? Math.max(0, allocationSpent(data, matchedEnvelope) - (editedAlreadyInEnvelope ? initial?.amount || 0 : 0)) : 0; const envelopeRemaining = matchedEnvelope ? allocationBudget(data, matchedEnvelope) - envelopeSpent : 0; const matchedWeek = matchedEnvelope && matchedEnvelope.weeklyPace !== false ? allocationWeekStatus(data, matchedEnvelope, date) : undefined; const initialInsideMatchedWeek = Boolean(initial && initial.date && matchedWeek && initial.date >= matchedWeek.start && initial.date <= matchedWeek.end); const adjustedWeekSpent = matchedWeek ? Math.max(0, matchedWeek.spent - (editedAlreadyInEnvelope && initialInsideMatchedWeek ? initial?.amount || 0 : 0)) : 0; const weekRemaining = matchedWeek ? matchedWeek.budget - adjustedWeekSpent : 0; const proposedAmount = parseRomanianAmount(amount); const envelopeAfter = envelopeRemaining - proposedAmount; const weekAfter = weekRemaining - proposedAmount;
  useEffect(() => {
    if (kind !== "expense") { if (allocationId !== "outside") setAllocationId("outside"); return; }
    const currentIsValid = allocationId !== "outside" && envelopeCandidates.some((allocation) => allocation.id === allocationId);
    if (!currentIsValid && allocationId !== "outside") setAllocationId(envelopeCandidates[0]?.id || "outside");
    if (!allocationChoiceTouched && allocationId === "outside" && envelopeCandidates[0]) setAllocationId(envelopeCandidates[0].id);
  }, [allocationChoiceTouched, allocationId, envelopeCandidateIds, kind]);
  const save = () => {
    const numeric = parseRomanianAmount(amount);
    const source = data.settings.paymentSources.find((item) => item.id === sourceId);
    const member = data.settings.members.find((item) => item.id === memberId);
    if (!title.trim()) return setError("Scrie o denumire pentru mișcare.");
    if (!numeric || numeric <= 0) return setError("Introdu o sumă mai mare decât zero.");
    if (!source || !member || !date) return setError("Alege data, membrul și sursa de plată.");
    if (kind === "expense" && allocationId !== "outside" && !matchedEnvelope) return setError("Plicul ales nu mai corespunde categoriei, membrului sau sursei. Alege din nou.");
    onSave({ id: initial?.id || newId("tx"), title: title.trim(), amount: numeric, kind, category: kind === "income" ? "Venit" : category, sourceId: source.id, source: source.name, memberId: member.id, person: member.name, date, note: note.trim() || undefined, allocationId: kind === "expense" ? allocationId : undefined, createdAt: initial?.createdAt || new Date().toISOString(), receiptId: initial?.receiptId });
    onClose();
  };
  return <Modal title={initial ? "Corectează mișcarea" : "Adaugă mișcare"} onClose={onClose}><div className="bf-segment"><button className={kind === "expense" ? "active expense" : ""} onClick={() => setKind("expense")}>Cheltuială</button><button className={kind === "income" ? "active income" : ""} onClick={() => setKind("income")}>Venit</button></div><div className="bf-form-grid"><Field label="Denumire"><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="ex. Cumpărături Lidl" /></Field><Field label="Sumă (lei)"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></Field><Field label="Data"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Cine a făcut mișcarea"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label={kind === "income" ? "Încasat în" : "Plătit din (sursa reală)"}><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {sourceOwner(source)} · {money(sourceBalance(data, source.id))}</option>)}</select></Field>{kind === "expense" && <Field label="Categorie"><select value={category} onChange={(event) => setCategory(event.target.value)}>{[...expenseCategories, ...data.settings.customCategories].map((item) => <option key={item}>{item}</option>)}</select></Field>}</div>{kind === "expense" && <section className="bf-envelope-choice"><div><p className="bf-kicker">BUGET REPARTIZAT</p><h3>Plicul compatibil este ales automat.</h3><p>Categoria, membrul și sursa reală găsesc plicul potrivit. Poți alege alt plic sau plată în afara plicurilor.</p></div><Field label="Plic de consum"><select value={allocationId} onChange={(event) => { setAllocationId(event.target.value); setAllocationChoiceTouched(true); }}><option value="outside">În afara plicurilor — nu consumă buget repartizat</option>{envelopeCandidates.map((allocation) => { const owner = data.settings.members.find((member) => member.id === allocation.memberId)?.name || "Familie / comun"; const source = data.settings.paymentSources.find((item) => item.id === allocation.sourceId); const remaining = Math.max(0, allocationBudget(data, allocation) - allocationSpent(data, allocation)); const week = allocation.weeklyPace === false ? undefined : allocationWeekStatus(data, allocation, date); return <option key={allocation.id} value={allocation.id}>{allocation.label} · {owner} · {source?.name || "orice sursă"} · {week ? `${money(Math.max(0, week.remaining))} în S${week.index}` : money(remaining)}</option>; })}</select></Field>{!envelopeCandidates.length && <small className="bf-envelope-empty">Nu există un plic pentru această combinație de categorie, membru și sursă. Poți înregistra cheltuiala în afara plicurilor sau crea unul în Plan.</small>}</section>}{matchedEnvelope ? <section className={`bf-envelope-match ${envelopeAfter < 0 || (matchedWeek && weekAfter < 0) ? "over" : ""}`}><p>{matchedWeek ? "SE VA LUA DIN PLICUL SĂPTĂMÂNII ACTIVE" : "SE VA LUA DIN PLIC"}</p><b>{matchedEnvelope.label} · {allocationMember} · {data.settings.paymentSources.find((source) => source.id === matchedEnvelope.sourceId)?.name || "sursa aleasă"}</b>{matchedWeek ? <span>S{matchedWeek.index}: {money(Math.max(0, weekRemaining))} rămași din {money(matchedWeek.budget)}{proposedAmount > 0 ? weekAfter < 0 ? ` · depășești tranșa cu ${money(Math.abs(weekAfter))}` : ` · după plată rămân ${money(weekAfter)}` : ""}</span> : <span>{money(Math.max(0, envelopeRemaining))} rămași din limita ajustată de {money(allocationBudget(data, matchedEnvelope))}</span>}{matchedEnvelope.note && <small>{matchedEnvelope.note}</small>}</section> : kind === "expense" && <section className="bf-envelope-match outside"><p>PLATĂ ÎN AFARA PLICURILOR</p><b>Va scădea doar soldul sursei reale de plată.</b><span>Nu consumă nicio limită repartizată pentru categorii.</span></section>}<Field label="Notiță opțională"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. cursă taxi, traseu, persoană, motiv" /></Field>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={save}><Check size={17} /> Salvează mișcarea</button></Modal>;
}

function GoalForm({ data, type, item, onSave, onClose }: { data: AppData; type: "debt" | "saving"; item?: Debt | SavingsGoal; onSave: (item: Debt | SavingsGoal) => void; onClose: () => void }) {
  const saving = type === "saving"; const old = item as SavingsGoal | undefined; const oldDebt = item as Debt | undefined;
  const [name, setName] = useState(item?.name || ""); const [one, setOne] = useState(item ? String(saving ? old?.current ?? 0 : oldDebt?.remaining ?? 0) : ""); const [two, setTwo] = useState(item ? String(saving ? old?.target ?? 0 : oldDebt?.monthly ?? 0) : ""); const [date, setDate] = useState(item?.dueDate || ""); const [memberId, setMemberId] = useState(item?.memberId || ""); const [error, setError] = useState("");
  const save = () => { const first = parseRomanianAmount(one); const second = parseRomanianAmount(two); if (!name.trim() || first < 0 || second < 0 || (saving && second <= 0)) return setError("Completează numele și sumele corecte."); if (saving) onSave({ id: item?.id || newId("goal"), name: name.trim(), current: first, target: second, due: date ? dateText(date, true) : "Fără termen", dueDate: date || undefined, memberId: memberId || undefined, tone: old?.tone || "honey" }); else onSave({ id: item?.id || newId("debt"), name: name.trim(), remaining: first, monthly: second, due: date ? dateText(date, true) : "Nespecificat", dueDate: date || undefined, memberId: memberId || undefined, tone: oldDebt?.tone || "coral" }); onClose(); };
  return <Modal title={saving ? "Obiectiv de economisire" : "Datorie sau rată"} onClose={onClose}><div className="bf-form-grid"><Field label={saving ? "Pentru ce economisiți?" : "Denumire"}><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder={saving ? "ex. Fond de siguranță" : "ex. Credit bancar"} /></Field><Field label="Aparține de"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}><option value="">Familie / comun</option>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label={saving ? "Strâns până acum (lei)" : "Sold rămas (lei)"}><input value={one} onChange={(event) => setOne(event.target.value)} inputMode="decimal" /></Field><Field label={saving ? "Țintă (lei)" : "Rată lunară (lei)"}><input value={two} onChange={(event) => setTwo(event.target.value)} inputMode="decimal" /></Field><Field label={saving ? "Data țintă" : "Scadență"}><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field></div>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={save}><Check size={17} /> Salvează</button></Modal>;
}

function DebtPaymentForm({ data, debt, onSave, onClose }: { data: AppData; debt: Debt; onSave: (data: AppData) => void; onClose: () => void }) {
  const defaultMemberId = debt.memberId || data.settings.members[0]?.id || ""; const [amount, setAmount] = useState(String(Math.min(debt.monthly || debt.remaining, debt.remaining))); const [date, setDate] = useState(isoToday()); const [memberId, setMemberId] = useState(defaultMemberId); const paymentSources = data.settings.paymentSources.filter((source) => !source.memberId || source.memberId === memberId); const [sourceId, setSourceId] = useState(data.settings.paymentSources.find((source) => source.memberId === defaultMemberId)?.id || data.settings.paymentSources.find((source) => !source.memberId)?.id || data.settings.paymentSources[0]?.id || ""); const [note, setNote] = useState(""); const [error, setError] = useState("");
  const pay = () => { const value = parseRomanianAmount(amount); if (value <= 0) return setError("Introdu o sumă mai mare decât zero."); if (value > debt.remaining) return setError(`Poți plăti cel mult ${money(debt.remaining)} pentru această datorie.`); const next = recordDebtPayment(data, { debtId: debt.id, amount: value, sourceId, memberId, date, note }); if (!next) return setError("Alege un membru și o sursă de plată valide."); if (!window.confirm(`Confirmi plata de ${money(value)} pentru „${debt.name}”? Soldul datoriei va deveni ${money(debt.remaining - value)}.`)) return; onSave(next); onClose(); };
  const ownerName = (sourceId: string) => data.settings.members.find((member) => member.id === data.settings.paymentSources.find((source) => source.id === sourceId)?.memberId)?.name || "Comun";
  return <Modal title={`Plătește rata · ${debt.name}`} onClose={onClose}><section className="bf-debt-payment-intro"><p className="bf-kicker">MIȘCARE REALĂ + DATORIE</p><p>Plata este adăugată în Jurnal și scade aceeași sumă din soldul rămas. Nu pornește plăți bancare automate.</p><strong>{money(debt.remaining)} rămași</strong></section><div className="bf-form-grid"><Field label="Sumă plătită (lei)"><input autoFocus value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" /></Field><Field label="Data plății"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Membru"><select value={memberId} onChange={(event) => { const nextMember = event.target.value; setMemberId(nextMember); const firstSource = data.settings.paymentSources.find((source) => !source.memberId || source.memberId === nextMember); if (firstSource) setSourceId(firstSource.id); }}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label="Plătit din"><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name} · {ownerName(source.id)} · {money(sourceBalance(data, source.id))}</option>)}</select></Field></div><Field label="Notiță opțională"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. rata august, plată parțială" /></Field>{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" onClick={pay}><Check size={17} /> Confirmă plata ratei</button></Modal>;
}

function BudgetBar({ used, total, tone = "green" }: { used: number; total: number; tone?: "green" | "gold" | "coral" }) { const percent = total > 0 ? Math.min(100, Math.max(0, used / total * 100)) : 0; return <div className={`bf-progress ${tone}`} aria-label={`${Math.round(percent)}% utilizat`}><span style={{ width: `${percent}%` }} /></div>; }

function planMath(data: AppData) {
  const plan = data.settings.salaryPlan;
  const planEnd = planEndDate(plan);
  const sourceIds = plan.sourceIds.length ? plan.sourceIds : data.settings.paymentSources.map((source) => source.id);
  const selected = data.settings.paymentSources.filter((source) => sourceIds.includes(source.id));
  const availableSources = selected.reduce((sum, source) => sum + sourceBalance(data, source.id), 0);
  const periodExpenses = data.transactions.filter((item) => item.kind === "expense" && inPlanPeriod(item.date, plan)).reduce((sum, item) => sum + item.amount, 0);
  const days = planEnd ? Math.max(1, Math.floor((new Date(`${planEnd}T12:00:00`).valueOf() - new Date(`${plan.periodStart}T12:00:00`).valueOf()) / 86400000) + 1) : 7;
  const weeks = Math.max(1, Math.ceil(days / 7));
  const weeklyPacedTotal = plan.allocations.filter((item) => item.weeklyPace !== false).reduce((sum, item) => sum + item.amount, 0);
  const weekly = plan.weeklyLimit || weeklyPacedTotal / weeks;
  const scheduled = pendingRecurringInPlan(data).reduce((sum, item) => sum + item.amount, 0);
  /** Banii deja puși deoparte în plicuri nu se scad a doua oară de aici: o cheltuială dintr-un plic mișcă doar plicul, nu și marja generală. */
  const reservedInEnvelopes = plan.allocations.reduce((sum, item) => sum + allocationStatus(data, item).remaining, 0);
  const remaining = availableSources - reservedInEnvelopes - scheduled;
  return { plan, planEnd, sourceIds, selected, availableSources, periodExpenses, scheduled, reservedInEnvelopes, remaining, days, weeks, weekly, weeklyPacedTotal };
}

function advisorSignals(data: AppData): AdvisorSignal[] {
  const math = planMath(data);
  const forecast = planForecast(data);
  const signals: AdvisorSignal[] = [];
  const pending = pendingRecurringInPlan(data).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  if (!math.plan.nextPayday) {
    signals.push({ id: "plan-needed", tone: "watch", eyebrow: "URMĂTORUL PAS", title: "Alege următorul venit", detail: "Planul are nevoie de o dată de salariu pentru a calcula ritmul sigur de cheltuire.", action: "plan", actionLabel: "Configurează planul" });
  } else if (math.remaining < 0) {
    signals.push({ id: "over-plan", tone: "risk", eyebrow: "ATENȚIE", title: `Planul este peste limită cu ${money(Math.abs(math.remaining))}`, detail: `Sunt incluse ${money(math.periodExpenses)} cheltuieli și ${money(math.scheduled)} rezervate până la ${dateText(math.planEnd || math.plan.nextPayday)}.`, action: "plan", actionLabel: "Revizuiește planul" });
  } else if (forecast.spentToDate > 0 && forecast.projectedRemaining < 0) {
    signals.push({ id: "pace-risk", tone: "risk", eyebrow: "RITM DE REVIZUIT", title: `La ritmul actual lipsesc ${money(Math.abs(forecast.projectedRemaining))}`, detail: `Cheltuielile sunt în medie ${money(forecast.paceDaily)} pe zi; ritmul sigur este ${money(forecast.safeDaily)} pe zi până la venit.`, action: "plan", actionLabel: "Ajustează planul" });
  } else {
    const daily = math.remaining / Math.max(1, math.days);
    signals.push({ id: "daily-pace", tone: "good", eyebrow: "RITM SIGUR", title: `${money(daily)} pe zi până la venit`, detail: `${money(math.remaining)} rămân după cheltuielile înregistrate și rezervele deja planificate.`, action: "plan", actionLabel: "Vezi calculele" });
  }
  if (pending[0]) {
    signals.push({ id: "next-recurring", tone: "watch", eyebrow: "SCADENȚĂ REZERVATĂ", title: `${pending[0].name} · ${money(pending[0].amount)}`, detail: `Este programată pentru ${dateText(pending[0].dueDate, true)} și este deja exclusă din suma disponibilă.`, action: "recurring", actionLabel: "Deschide scadențele" });
  }
  const allocation = data.settings.salaryPlan.allocations.map((item) => ({ item, ...allocationStatus(data, item) })).sort((a, b) => b.usage - a.usage)[0];
  if (allocation && allocation.state !== "healthy") {
    const over = allocation.state === "over";
    signals.push({ id: `allocation-${allocation.item.id}`, tone: over ? "risk" : "watch", eyebrow: over ? "PLIC DEPĂȘIT" : "APROAPE DE LIMITĂ", title: `${allocation.item.label}: ${money(Math.max(0, allocation.remaining))} rămași`, detail: `${money(allocation.spent)} cheltuiți din limita ajustată de ${money(allocation.budget)} în perioada activă.`, action: "plan", actionLabel: "Vezi plicul" });
  }
  const goal = data.savings.filter((item) => item.target > item.current).sort((a, b) => (b.target - b.current) - (a.target - a.current))[0];
  if (goal && signals.length < 3) signals.push({ id: `goal-${goal.id}`, tone: "good", eyebrow: "OBIECTIV COMUN", title: `${money(goal.target - goal.current)} până la ${goal.name}`, detail: `Progres actual: ${money(goal.current)} din ${money(goal.target)}.`, action: "objectives", actionLabel: "Vezi obiectivul" });
  return signals.slice(0, 3);
}

/**
 * Atelierul Financiar 3.0 — spațiu mobil pentru situația zilei, nu un dashboard de module egale.
 * Marja, decizia și activitatea recentă au prioritate, iar detaliile se deschid în traseele proprii.
 */
function TodayView({ data, onAdd, onGo }: { data: AppData; onAdd: () => void; onGo: (view: MainView) => void }) {
  const math = planMath(data); const forecast = planForecast(data); const signals = advisorSignals(data); const balance = financialBalance(data, math.plan.periodStart, math.planEnd); const [dismissedAlerts, setDismissedAlerts] = useState<string[]>([]); const [shownTrancheKey, setShownTrancheKey] = useState("");
  const envelopes = data.settings.salaryPlan.allocations.map((item) => ({ item, ...allocationStatus(data, item) })); const topEnvelope = [...envelopes].sort((a, b) => b.usage - a.usage)[0]; const activeEnvelopeAlert = envelopes.filter((item) => item.state !== "healthy" && !dismissedAlerts.includes(item.item.id)).sort((a, b) => (b.state === "over" ? 2 : 1) - (a.state === "over" ? 2 : 1))[0]; const lastMoves = data.transactions.slice(0, 3); const overPlan = math.remaining < 0; const daily = math.plan.nextPayday ? forecast.safeDaily : 0;
  const activeTranche = math.planEnd ? currentCalendarBudgetWeek(math.weeklyPacedTotal, math.plan.periodStart, math.planEnd, isoToday()) : undefined; const activeTrancheKey = activeTranche ? calendarBudgetWeekKey(activeTranche) : ""; const showTrancheNotice = Boolean(activeTranche && shownTrancheKey === activeTrancheKey);
  useEffect(() => { if (!activeTranche || !activeTrancheKey || data.settings.seenWeeklyPlanTranches.includes(activeTrancheKey) || shownTrancheKey === activeTrancheKey) return; setShownTrancheKey(activeTrancheKey); window.dispatchEvent(new CustomEvent("buget-familie:local-settings", { detail: { seenWeeklyPlanTranches: [...data.settings.seenWeeklyPlanTranches, activeTrancheKey].slice(-80) } })); }, [activeTranche, activeTrancheKey, data.settings.seenWeeklyPlanTranches, shownTrancheKey]);
  const openSignal = (action: AdvisorAction) => onGo(action === "plan" ? "plan" : action === "objectives" ? "obligations" : action === "journal" ? "journal" : "obligations");
  return <div className="bf-page bf-today-workspace"><section className={`bf-today-situation ${overPlan ? "risk" : ""} ${!showTrancheNotice && !activeEnvelopeAlert ? "paired" : ""}`}><div className="bf-today-situation-top"><span className="bf-status-chip"><i /> {overPlan ? "Plan de revizuit" : "Ritm urmărit"}</span><time dateTime={isoToday()}>{dateText(isoToday(), true)}</time></div><div className="bf-today-situation-number"><p>{overPlan ? "Peste limita planului" : "Bani nerepartizați"}</p><strong>{money(Math.abs(math.remaining))}</strong><span>{overPlan ? "de acoperit prin limită, plicuri sau cheltuieli flexibile" : math.plan.nextPayday ? `${math.days} zile rămase · ritm prudent ${money(daily)}/zi` : "setează venitul următor pentru a calcula ritmul"}</span></div><div className="bf-today-situation-actions"><button className="bf-today-add" onClick={onAdd}><Plus size={20} /> Înregistrează mișcare</button><button className="bf-today-plan-link" onClick={() => onGo("plan")}>Deschide planul <ChevronRight size={16} /></button></div></section>{showTrancheNotice && activeTranche && <aside className="bf-weekly-tranche-notice" role="status" aria-live="polite"><CalendarClock size={19} /><div><p>TRANȘA S{activeTranche.index} A ÎNCEPUT</p><strong>{formatDate(activeTranche.start, { day: "2-digit", month: "short" })} – {formatDate(activeTranche.end, { day: "2-digit", month: "short" })}</strong><span>Ritmul acestei tranșe este {money(activeTranche.amount)} pentru {activeTranche.days} {activeTranche.days === 1 ? "zi" : "zile"}.</span></div><button onClick={() => onGo("plan")}>Plan</button><button className="dismiss" aria-label="Ascunde alerta tranșei săptămânale" onClick={() => setShownTrancheKey("")}><X size={16} /></button></aside>}{activeEnvelopeAlert && <aside className={`bf-envelope-live-notice ${activeEnvelopeAlert.state}`} role="status" aria-live="polite"><BellRing size={19} /><div><p>{activeEnvelopeAlert.state === "over" ? "PLIC DEPĂȘIT" : "APROAPE DE LIMITĂ"}</p><strong>{activeEnvelopeAlert.item.label}</strong><span>{activeEnvelopeAlert.state === "over" ? `${money(Math.abs(activeEnvelopeAlert.remaining))} peste limita alocată.` : `${Math.round(activeEnvelopeAlert.usage * 100)}% din limită este deja consumată.`}</span></div><button onClick={() => onGo("plan")}>Vezi</button><button className="dismiss" aria-label={`Ascunde alerta pentru ${activeEnvelopeAlert.item.label}`} onClick={() => setDismissedAlerts((current) => [...current, activeEnvelopeAlert.item.id])}><X size={16} /></button></aside>}<section className="bf-today-decision"><div className="bf-today-decision-heading"><div><p className="bf-kicker">DECIZIA URMĂTOARE</p><h1>Ce are nevoie <em>gospodăria acum.</em></h1></div><button onClick={() => onGo("insights")}><LayoutDashboard size={17} /> Vezi analiza</button></div><div className="bf-decision-stack">{signals.map((signal, index) => <button className={`bf-decision-row ${signal.tone} ${index === 0 ? "primary" : ""}`} key={signal.id} onClick={() => openSignal(signal.action)}><span className="bf-decision-index">0{index + 1}</span><span><small>{signal.eyebrow}</small><b>{signal.title}</b><em>{signal.detail}</em></span><ChevronRight size={19} /></button>)}{!signals.length && <button className="bf-decision-row good primary" onClick={() => onGo("plan")}><span className="bf-decision-index">01</span><span><small>PLANUL DE LUCRU</small><b>Configurează următorul venit</b><em>Gospodăria are nevoie de intervalul următor pentru a calcula ritmul.</em></span><ChevronRight size={19} /></button>}</div></section><section className="bf-today-measurements" aria-label="Măsurători financiare curente"><article><span>SURSE UTILIZABILE</span><b>{money(balance.liquidFunds)}</b><small>banii incluși în registru</small></article><article><span>OBLIGAȚII CONFIRMATE</span><b className={balance.monthlyRates > 0 ? "attention" : ""}>{money(balance.monthlyRates)}</b><small>{data.debts.length} de revizuit lunar</small></article><article><span>{topEnvelope ? `LIMITĂ: ${topEnvelope.item.label}` : "PLICURI / LIMITE"}</span><b className={topEnvelope?.state === "over" ? "negative" : ""}>{topEnvelope ? `${Math.round(topEnvelope.usage * 100)}%` : "—"}</b><small>{topEnvelope ? `${money(Math.max(0, topEnvelope.remaining))} rămași pentru perioadă` : "creează prima limită"}</small></article></section><section className="bf-today-activity"><div className="bf-section-heading"><div><p className="bf-kicker">ACTIVITATE RECENTĂ</p><h2>Ce s-a înregistrat</h2></div><button onClick={() => onGo("journal")}>Toate mișcările <ChevronRight size={15} /></button></div>{lastMoves.length ? <div className="bf-today-activity-list">{lastMoves.map((item) => <article key={item.id}><span className={`bf-tx-icon ${item.kind}`}>{item.kind === "income" ? <ArrowDownRight size={16} /> : <ArrowUpRight size={16} />}</span><div><b>{item.title}</b><small>{dateText(item.date)} · {item.person} · {item.category}</small></div><strong className={item.kind}>{item.kind === "income" ? "+" : "−"}{fmtExact.format(item.amount)}</strong></article>)}</div> : <button className="bf-today-empty-activity" onClick={onAdd}><ReceiptText size={20} /><span><b>Registrul zilei este pregătit.</b><small>Înregistrează prima cheltuială sau încasare.</small></span><Plus size={18} /></button>}</section>{(data.transactions.length > 0 || data.settings.members.length > 1 || data.settings.salaryPlan.allocations.length > 0) && <WeeklySummaryPanel data={data} onOpenJournal={() => onGo("journal")} />}</div>;
}

function DebtPaymentHistory({ data, debt }: { data: AppData; debt: Debt }) { const history = debtPaymentHistory(data, debt.id); if (!history.length) return <p className="bf-debt-history empty">Nu există încă plăți confirmate pentru această datorie.</p>; return <div className="bf-debt-history"><p>PLĂȚI ÎNREGISTRATE</p>{history.slice(0, 4).map((payment) => <div key={payment.id}><span><b>{payment.title.includes("achitată integral") ? "Achitată integral" : "Plată parțială"}</b><small>{dateText(payment.date, true)} · {payment.source}</small></span><span><strong>{money(payment.amount)}</strong><small>rămân {money(payment.debtRemainingAfter ?? debt.remaining)}</small></span></div>)}</div>; }

/** Atelierul Financiar 3.0 — obligațiile devin o axă de protejat: datorii, plăți confirmate, economii și scadențe. */
function ObjectivesView({ data, onEditDebt, onEditSaving, onPayDebt, onDeleteDebt, onDeleteSaving, openDebt, openSaving, onOpenRecurring, onPayRecurring }: { data: AppData; onEditDebt: (item: Debt) => void; onEditSaving: (item: SavingsGoal) => void; onPayDebt: (item: Debt) => void; onDeleteDebt: (id: string) => void; onDeleteSaving: (id: string) => void; openDebt: () => void; openSaving: () => void; onOpenRecurring: () => void; onPayRecurring: (id: string) => void }) {
  const totalDebt = data.debts.reduce((sum, item) => sum + item.remaining, 0); const totalSavings = data.savings.reduce((sum, item) => sum + item.current, 0); const monthlyRates = data.debts.reduce((sum, item) => sum + item.monthly, 0);
  const upcoming = [
    ...data.debts.filter((item) => item.dueDate).map((item) => ({ id: `debt-${item.id}`, date: item.dueDate!, label: item.name, detail: `Rată ${money(item.monthly)}/lună`, amount: item.remaining, onConfirm: () => onPayDebt(item) })),
    ...pendingRecurringInPlan(data).map((item) => ({ id: `recurring-${item.id}`, date: item.dueDate, label: item.name, detail: item.category, amount: item.amount, onConfirm: () => onPayRecurring(item.id) })),
  ].sort((a, b) => a.date.localeCompare(b.date)).slice(0, 3);
  return <div className="bf-page bf-obligations-workspace"><header className="bf-obligations-header"><div><p className="bf-kicker">OBLIGAȚII ȘI REZERVE</p><h1>Ce trebuie <em>protejat.</em></h1><p>Ratele devin mișcări doar după confirmare. Economiile rămân distincte de soldurile surselor.</p></div><span><BellRing size={25} /></span></header><section className="bf-obligation-timeline"><div className="bf-section-heading"><div><p className="bf-kicker">URMEAZĂ</p><h2>Următoarele scadențe</h2></div></div>{upcoming.length ? <div className="bf-obligation-timeline-list">{upcoming.map((entry) => <article className="bf-obligation-entry" key={entry.id}><div className="bf-obligation-entry-main"><span><BellRing size={17} /></span><div><b>{entry.label}</b><small>{dateText(entry.date, true)} · {entry.detail}</small></div><strong>{money(entry.amount)}</strong></div><div className="bf-obligation-entry-actions"><button className="pay" onClick={entry.onConfirm}><Check size={16} /> Confirmă plata</button></div></article>)}</div> : <div className="bf-obligation-empty"><BellRing size={21} /><span><b>Nu ai scadențe apropiate.</b><small>Adaugă o dată la datorii sau o scadență recurentă pentru a le vedea aici.</small></span></div>}</section><section className="bf-obligation-ledger"><article className="debt"><span>Sold datorii</span><b>{money(totalDebt)}</b><small>{money(monthlyRates)} rate declarate / lună</small></article><article className="savings"><span>Economii urmărite</span><b>{money(totalSavings)}</b><small>{data.savings.length} obiective înregistrate</small></article><button onClick={onOpenRecurring}><CalendarClock size={18} /><span>Scadențe programate</span><b>{data.recurring.length}</b><ChevronRight size={16} /></button></section><section className="bf-obligation-actions"><button onClick={openDebt}><Plus size={17} /> Adaugă datorie</button><button onClick={openSaving}><Plus size={17} /> Creează economisire</button></section><div className="bf-obligation-lanes"><section className="bf-obligation-lane debt"><header><div><p className="bf-kicker">DE PLĂTIT</p><h2>Rate și împrumuturi</h2></div><span>{data.debts.length}</span></header>{data.debts.map((debt) => <article className="bf-obligation-entry" key={debt.id}><div className="bf-obligation-entry-main"><span><BellRing size={17} /></span><div><b>{debt.name}</b><small>{debt.due} · rată {money(debt.monthly)}/lună</small></div><strong>{money(debt.remaining)}</strong></div><DebtPaymentHistory data={data} debt={debt} /><div className="bf-obligation-entry-actions"><button className="pay" onClick={() => onPayDebt(debt)}><Check size={16} /> Confirmă plata</button><button onClick={() => onEditDebt(debt)}><Pencil size={15} /> Editează</button><button className="delete" aria-label={`Șterge ${debt.name}`} onClick={() => onDeleteDebt(debt.id)}><Trash2 size={16} /></button></div></article>)}{!data.debts.length && <div className="bf-obligation-empty"><BellRing size={21} /><span><b>Nu ai datorii înregistrate.</b><small>Adaugă doar obligațiile pe care vrei să le rezervi în plan.</small></span><button onClick={openDebt}>Adaugă</button></div>}</section><section className="bf-obligation-lane savings"><header><div><p className="bf-kicker">DE CONSTRUIT</p><h2>Economii și obiective</h2></div><span>{data.savings.length}</span></header>{data.savings.map((saving) => <article className="bf-obligation-entry" key={saving.id}><div className="bf-obligation-entry-main"><span><PiggyBank size={17} /></span><div><b>{saving.name}</b><small>{saving.due}</small></div><strong>{money(saving.current)}</strong></div><div className="bf-obligation-progress"><BudgetBar used={saving.current} total={saving.target} tone="gold" /><small>{money(Math.max(0, saving.target - saving.current))} rămași până la {money(saving.target)}</small></div><div className="bf-obligation-entry-actions"><button onClick={() => onEditSaving(saving)}><Pencil size={15} /> Editează</button><button className="delete" aria-label={`Șterge ${saving.name}`} onClick={() => onDeleteSaving(saving.id)}><Trash2 size={16} /></button></div></article>)}{!data.savings.length && <div className="bf-obligation-empty"><PiggyBank size={21} /><span><b>Nu ai obiective de economisire.</b><small>Începe cu fondul de siguranță sau un obiectiv concret.</small></span><button onClick={openSaving}>Creează</button></div>}</section></div></div>;
}

function ReceiptForm({ data, onSave, onClose }: { data: AppData; onSave: (item: Receipt) => void | Promise<void>; onClose: () => void }) {
  const [vendor, setVendor] = useState(""); const [amount, setAmount] = useState(""); const [date, setDate] = useState(isoToday()); const [sourceId, setSourceId] = useState(data.settings.paymentSources[0]?.id || ""); const [memberId, setMemberId] = useState(data.settings.members[0]?.id || ""); const [note, setNote] = useState(""); const [images, setImages] = useState<string[]>([]); const [lines, setLines] = useState<Array<{ id: string; category: string; amount: string; label: string }>>([{ id: newId("receipt-line"), category: "Alimente", amount: "", label: "" }]); const [ocrText, setOcrText] = useState(""); const [ocrSummary, setOcrSummary] = useState(""); const [busy, setBusy] = useState(false); const [progress, setProgress] = useState(0); const [error, setError] = useState("");
  const categories = [...expenseCategories, ...data.settings.customCategories];
  const lineTotal = lines.reduce((sum, line) => sum + parseRomanianAmount(line.amount), 0);
  const pick = async (files?: FileList | null) => {
    const selected = files ? Array.from(files) : [];
    if (!selected.length) return;
    if (images.length + selected.length > 2) return setError("Un bon poate avea maximum două fotografii. Elimină una înainte de a adăuga alta.");
    try { setBusy(true); setError(""); const { compressReceiptImage } = await import("@/lib/receipt-utils"); const compressed = await Promise.all(selected.map(compressReceiptImage)); setImages((current) => [...current, ...compressed]); } catch (reason) { setError(reason instanceof Error ? reason.message : "Poza bonului nu a putut fi procesată."); } finally { setBusy(false); }
  };
  const scan = async () => {
    try { setBusy(true); setError(""); setOcrSummary(""); setProgress(0); const { readReceiptLocally } = await import("@/lib/receipt-utils"); const result = await readReceiptLocally(images, setProgress); setOcrText(result.text); if (result.amount) setAmount(String(result.amount)); if (result.date) setDate(result.date); if (result.text && !note.trim()) setNote(result.text.slice(0, 1400)); if (result.items.length) { const suggestedLines = result.items.map((item) => ({ id: newId("receipt-line"), category: categories.includes(item.category) ? item.category : "Alimente", amount: String(item.amount), label: item.label })); setLines(suggestedLines); const detectedTotal = result.items.reduce((sum, item) => sum + item.amount, 0); setOcrSummary(`Am propus ${result.items.length} produs${result.items.length === 1 ? "" : "e"} cu prețuri individuale (${fmtExact.format(detectedTotal)}). Verifică produsele, categoriile și totalul înainte de salvare.`); } else { setOcrSummary("Am citit textul și totalul, dar nu am identificat sigur linii de produse. Completează repartizarea manual."); } } catch (reason) { setError(reason instanceof Error ? reason.message : "Textul de pe bon nu a putut fi citit."); } finally { setBusy(false); setProgress(0); }
  };
  const updateLine = (id: string, patch: Partial<(typeof lines)[number]>) => setLines((current) => current.map((line) => line.id === id ? { ...line, ...patch } : line));
  const save = async () => {
    const numeric = parseRomanianAmount(amount);
    const normalizedLines: ReceiptLine[] = lines.map((line) => ({ id: line.id, category: line.category, amount: parseRomanianAmount(line.amount), label: line.label.trim() || undefined })).filter((line) => line.amount > 0);
    if (normalizedLines.length === 0 && numeric > 0 && lines.length === 1) normalizedLines.push({ id: lines[0].id, category: lines[0].category, amount: numeric, label: lines[0].label.trim() || undefined });
    const splitTotal = normalizedLines.reduce((sum, line) => sum + line.amount, 0);
    if (!vendor.trim() || numeric <= 0 || !sourceId || !memberId) return setError("Completează magazinul, totalul, membrul și sursa.");
    if (!normalizedLines.length || Math.abs(numeric - splitTotal) > 0.01) return setError(`Repartizarea este ${fmtExact.format(splitTotal)}, dar totalul bonului este ${fmtExact.format(numeric)}. Corectează liniile înainte de salvare.`);
    try { setBusy(true); setError(""); const id = newId("receipt"); const imageKeys = images.length ? await storeReceiptImages(id, images) : []; await onSave({ id, vendor: vendor.trim(), amount: numeric, date, category: normalizedLines[0].category, lines: normalizedLines, sourceId, memberId, note: note.trim() || undefined, imageKeys: imageKeys.length ? imageKeys : undefined, ocrText: ocrText || undefined }); onClose(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Bonul nu a putut fi salvat pe telefon."); } finally { setBusy(false); }
  };
  return <Modal title="Adaugă bon" onClose={onClose}><div className="bf-receipt-intro"><p className="bf-kicker">BON CU REPARTIZARE</p><p>Poți fotografia un bon lung în două părți; imaginile se comprimă și rămân doar în stocarea locală securizată a telefonului.</p></div><div className="bf-form-grid"><Field label="Magazin"><input autoFocus value={vendor} onChange={(event) => setVendor(event.target.value)} placeholder="ex. Lidl" /></Field><Field label="Total (lei)"><input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0,00" /></Field><Field label="Data"><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Membru"><select value={memberId} onChange={(event) => setMemberId(event.target.value)}>{data.settings.members.map((member) => <option key={member.id} value={member.id}>{member.name}</option>)}</select></Field><Field label="Plătit din"><select value={sourceId} onChange={(event) => setSourceId(event.target.value)}>{data.settings.paymentSources.map((source) => <option key={source.id} value={source.id}>{source.name}</option>)}</select></Field></div><section className="bf-receipt-images"><div><p className="bf-kicker">FOTOGRAFIILE BONULUI</p><strong>{images.length}/2 imagini</strong></div><label className="bf-upload-control"><Camera size={18} /> {busy && !progress ? "Comprimăm…" : "Adaugă poze"}<input type="file" accept="image/*" capture="environment" multiple disabled={busy || images.length >= 2} onChange={(event) => { void pick(event.target.files); event.currentTarget.value = ""; }} /></label>{images.length > 0 && <button className="bf-ocr-button" disabled={busy} onClick={() => void scan()}><Bot size={17} /> {busy && progress ? `Citim ${progress}%` : "Citește produsele și prețurile local"}</button>}<div className="bf-receipt-preview-grid">{images.map((image, index) => <figure key={image}><img src={image} alt={`Previzualizare bon partea ${index + 1}`} /><button aria-label={`Elimină fotografia ${index + 1}`} onClick={() => setImages((current) => current.filter((_, imageIndex) => imageIndex !== index))}><X size={15} /></button></figure>)}</div>{ocrSummary && <p className="bf-ocr-info" role="status"><Bot size={16} /> {ocrSummary}</p>}</section><section className="bf-receipt-split"><div className="bf-split-heading"><div><p className="bf-kicker">PRODUSE ȘI CATEGORII</p><h3>{fmtExact.format(lineTotal)} din {amount ? fmtExact.format(parseRomanianAmount(amount)) : "0,00 RON"}</h3></div><button className="bf-secondary" onClick={() => setLines((current) => [...current, { id: newId("receipt-line"), category: "Alimente", amount: "", label: "" }])}><Plus size={16} /> Produs</button></div>{lines.map((line) => <div className="bf-split-line" key={line.id}><select aria-label="Categorie bon" value={line.category} onChange={(event) => updateLine(line.id, { category: event.target.value })}>{categories.map((item) => <option key={item}>{item}</option>)}</select><input aria-label="Preț produs" value={line.amount} onChange={(event) => updateLine(line.id, { amount: event.target.value })} inputMode="decimal" placeholder="lei" /><input aria-label="Produs" value={line.label} onChange={(event) => updateLine(line.id, { label: event.target.value })} placeholder="ex. fructe" />{lines.length > 1 && <button aria-label="Elimină produsul" onClick={() => setLines((current) => current.filter((entry) => entry.id !== line.id))}><Trash2 size={16} /></button>}</div>)}<small>OCR-ul propune linii editabile. Fiecare linie devine o cheltuială reală, iar totalul liniilor trebuie să fie egal cu totalul bonului.</small></section>{ocrText && <Field label="Text citit local (verifică înainte de salvare)"><textarea value={note} onChange={(event) => setNote(event.target.value)} /></Field>}{!ocrText && <Field label="Produse / notiță"><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="ex. apă, fructe, detergent" /></Field>}{error && <p className="bf-form-error" role="alert">{error}</p>}<button className="bf-primary full" disabled={busy} onClick={() => void save()}><Check size={17} /> Salvează bonul și cheltuielile</button></Modal>;
}

function MoreView({ tab, setTab, data, onChange, onAddReceipt, onDeleteReceipt, onOpenDebt, onOpenSaving, receiptStorageNotice }: { tab: MoreView; setTab: (value: MoreView) => void; data: AppData; onChange: (value: AppData) => void; onAddReceipt: () => void; onDeleteReceipt: (id: string) => void; onOpenDebt: () => void; onOpenSaving: () => void; receiptStorageNotice?: string }) {
  const isCollaborative = data.settings.members.length > 1; const tabs: { id: MoreView; label: string; icon: typeof SlidersHorizontal }[] = [{ id: "overview", label: "Instrumente", icon: MoreHorizontal }, { id: "debts", label: "Datorii", icon: BellRing }, { id: "savings", label: "Economii", icon: PiggyBank }, { id: "receipts", label: "Bonuri", icon: ReceiptText }, { id: "recurring", label: "Scadențe", icon: CalendarDays }, { id: "reports", label: "Statistici", icon: LayoutDashboard }, { id: "assistant", label: "Asistent", icon: Bot }, { id: "settings", label: "Setări", icon: Settings }, { id: "sync", label: "Sync", icon: Cloud }, { id: "guide", label: "Ghid", icon: BookOpen }];
  const setSettings = (patch: Partial<AppData["settings"]>) => onChange({ ...data, settings: { ...data.settings, ...patch } });
  const content = () => {
    if (tab === "overview") return <div className="bf-more-grid"><button onClick={onOpenDebt}><BellRing size={20} /><b>Datorii</b><span>{data.debts.length} active</span></button><button onClick={onOpenSaving}><PiggyBank size={20} /><b>Economii</b><span>{data.savings.length} obiective</span></button><button onClick={onAddReceipt}><Camera size={20} /><b>Bonuri</b><span>{data.receipts.length} salvate</span></button><button onClick={() => setTab("recurring")}><CalendarClock size={20} /><b>Scadențe</b><span>{data.recurring.length} programate</span></button><button onClick={() => setTab("assistant")}><Bot size={20} /><b>Asistent</b><span>explică datele</span></button><button onClick={() => setTab("settings")}><Settings size={20} /><b>{isCollaborative ? "Setări familie" : "Setări profil"}</b><span>{isCollaborative ? "membri și surse" : "surse și categorii"}</span></button><button onClick={() => setTab("sync")}><Cloud size={20} /><b>Sincronizare</b><span>{isCollaborative ? "spațiu conectat" : "opțională între telefoane"}</span></button><button onClick={() => setTab("guide")}><BookOpen size={20} /><b>Manual</b><span>configurare și utilizare</span></button></div>;
    if (tab === "debts") return <div className="bf-more-list">{data.debts.map((debt) => <article key={debt.id}><span><b>{debt.name}</b><small>{debt.due}</small></span><strong>{money(debt.remaining)}</strong><em>{money(debt.monthly)}/lună</em></article>)}{!data.debts.length && <div className="bf-empty-state slim"><BellRing size={23} /><h2>Nicio datorie</h2><button className="bf-primary" onClick={onOpenDebt}><Plus size={16} /> Adaugă datorie</button></div>}</div>;
    if (tab === "savings") return <div className="bf-more-list">{data.savings.map((saving) => <article key={saving.id}><span><b>{saving.name}</b><small>{saving.due}</small></span><strong>{money(saving.current)}</strong><BudgetBar used={saving.current} total={saving.target} tone="gold" /></article>)}{!data.savings.length && <div className="bf-empty-state slim"><PiggyBank size={23} /><h2>Niciun obiectiv</h2><button className="bf-primary" onClick={onOpenSaving}><Plus size={16} /> Creează obiectiv</button></div>}</div>;
    if (tab === "receipts") return <div>{receiptStorageNotice && <p className="bf-notice" role="status"><ShieldCheck size={15} /> {receiptStorageNotice}</p>}<button className="bf-primary bf-inline-add" onClick={onAddReceipt}><Camera size={17} /> Adaugă bon</button><div className="bf-receipt-list">{data.receipts.map((receipt) => <article key={receipt.id}><ReceiptThumbnail receipt={receipt} /><div><b>{receipt.vendor}</b><small>{dateText(receipt.date)} · {receipt.lines?.length || 1} categorie{(receipt.lines?.length || 1) === 1 ? "" : "i"}</small><p>{receipt.lines?.map((line) => `${line.category}: ${money(line.amount)}`).join(" · ") || receipt.note || "Fără detalii"}</p>{(receipt.imageKeys?.length || (receipt.imageData2 ? 2 : receipt.imageData ? 1 : 0)) > 1 && <small>Bon în două fotografii</small>}</div><strong>{money(receipt.amount)}</strong><button aria-label={`Șterge bonul ${receipt.vendor}`} onClick={() => onDeleteReceipt(receipt.id)}><Trash2 size={16} /></button></article>)}{!data.receipts.length && <div className="bf-empty-state slim"><ReceiptText size={23} /><h2>Niciun bon</h2><p>Un bon poate avea două poze și mai multe categorii; fiecare categorie creează o cheltuială legată de același bon.</p></div>}</div></div>;
    if (tab === "recurring") return <Suspense fallback={<div className="bf-lazy-panel">Pregătim scadențele…</div>}><RecurringPanel data={data} onChange={onChange} /></Suspense>;
    if (tab === "reports") return <Suspense fallback={<div className="bf-lazy-panel">Pregătim statisticile…</div>}><ReportsPanel data={data} /></Suspense>;
    if (tab === "assistant") return <Suspense fallback={<div className="bf-lazy-panel">Pregătim asistentul…</div>}><AdvisorPanel data={data} /></Suspense>;
    if (tab === "settings") return <SettingsPanel data={data} onChange={onChange} onReset={() => { if (!window.confirm("Ștergi toate datele locale de pe acest dispozitiv?")) return; void clearReceiptImageStorage(); onChange(createEmptyAppData()); }} />;
    if (tab === "guide") return <FamilyGuide />;
    return <SyncPanel data={data} onChange={onChange} />;
  };
  return <div className="bf-page bf-utilities-workspace"><header className="bf-topline compact"><div><p className="bf-kicker">INSTRUMENTE</p><h1>Alege un <em>instrument.</em></h1></div></header><div className="bf-more-tab-region"><p className="bf-more-swipe-hint" aria-hidden="true">Glisează pentru mai multe</p><div className="bf-more-tabs" role="tablist" aria-label="Categorii de instrumente">{tabs.map((item) => { const Icon = item.icon; return <button role="tab" aria-selected={tab === item.id} key={item.id} className={tab === item.id ? "active" : ""} onClick={() => setTab(item.id)}><Icon size={16} /> {item.label}</button>; })}</div></div>{content()}</div>;
}

function SettingsPanel({ data, onChange, onReset }: { data: AppData; onChange: (value: AppData) => void; onReset: () => void }) {
  const importBackup = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; void file.text().then((raw) => { const backup = parseBackup(raw); if (!window.confirm(`Înlocuiești datele locale cu backup-ul din ${new Date(backup.exportedAt).toLocaleDateString("ro-RO")}?`)) return; onChange(normalizeAppData(backup.data)); }).catch((reason) => window.alert(reason instanceof Error ? reason.message : "Backup-ul nu a putut fi importat.")); event.target.value = ""; };
  const [member, setMember] = useState(""); const [source, setSource] = useState(""); const [kind, setKind] = useState<PaymentKind>("card"); const [owner, setOwner] = useState(data.settings.members[0]?.id || ""); const [category, setCategory] = useState("");
  const settings = data.settings; const change = (patch: Partial<typeof settings>) => onChange({ ...data, settings: { ...settings, ...patch } });
  const addMember = () => { if (!member.trim()) return; if (settings.members.some((item) => item.name.toLowerCase() === member.trim().toLowerCase())) return; change({ members: [...settings.members, { id: newId("member"), name: member.trim() }] }); setMember(""); };
  const addSource = () => { if (!source.trim()) return; change({ paymentSources: [...settings.paymentSources, { id: newId("source"), name: source.trim(), kind, memberId: kind === "transfer" ? undefined : owner, openingBalance: 0 }] }); setSource(""); };
  return <div className="bf-settings"><section><p className="bf-kicker">FAMILIE</p><Field label="Numele familiei"><input value={settings.familyName} onChange={(event) => change({ familyName: event.target.value })} /></Field><Field label="Numele tău"><input value={settings.memberName} onChange={(event) => change({ memberName: event.target.value })} /></Field><Field label="Cod local de familie" hint="Codul ajută la verificarea exportului manual."><input value={settings.familyCode} onChange={(event) => change({ familyCode: event.target.value.toUpperCase() })} /><button className="bf-link-button" onClick={() => change({ familyCode: createFamilyCode() })}><RotateCcw size={14} /> Cod nou</button></Field></section><section><p className="bf-kicker">MEMBRI</p><div className="bf-chip-list">{settings.members.map((item) => <span key={item.id}>{item.name}{settings.members.length > 1 && <button onClick={() => change({ members: settings.members.filter((memberItem) => memberItem.id !== item.id) })}><X size={14} /></button>}</span>)}</div><div className="bf-mini-form"><input value={member} onChange={(event) => setMember(event.target.value)} placeholder="ex. Soția" /><button onClick={addMember}>Adaugă</button></div></section><section><p className="bf-kicker">SURSE ȘI SOLD INITIAL</p>{settings.paymentSources.map((item) => <div className="bf-source-edit" key={item.id}><span><b>{item.name}</b><small>{sourceKindName[item.kind]} · {settings.members.find((memberItem) => memberItem.id === item.memberId)?.name || "Comun"}</small></span><label><small>Sold inițial</small><input inputMode="decimal" value={String(item.openingBalance)} onChange={(event) => change({ paymentSources: settings.paymentSources.map((sourceItem) => sourceItem.id === item.id ? { ...sourceItem, openingBalance: Math.max(0, parseRomanianAmount(event.target.value)) } : sourceItem) })} /></label><strong>{money(sourceBalance(data, item.id))}</strong></div>)}<div className="bf-source-builder"><input value={source} onChange={(event) => setSource(event.target.value)} placeholder="ex. Card soție" /><select value={kind} onChange={(event) => setKind(event.target.value as PaymentKind)}>{Object.entries(sourceKindName).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select><select value={owner} disabled={kind === "transfer"} onChange={(event) => setOwner(event.target.value)}>{settings.members.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><button onClick={addSource}>Adaugă</button></div></section><section><p className="bf-kicker">CATEGORII PROPRII</p><div className="bf-chip-list">{settings.customCategories.map((item) => <span key={item}>{item}<button onClick={() => change({ customCategories: settings.customCategories.filter((categoryItem) => categoryItem !== item) })}><X size={14} /></button></span>)}</div><div className="bf-mini-form"><input value={category} onChange={(event) => setCategory(event.target.value)} placeholder="ex. Taxi" /><button onClick={() => { if (category.trim() && !settings.customCategories.includes(category.trim())) { change({ customCategories: [...settings.customCategories, category.trim()] }); setCategory(""); } }}>Adaugă</button></div></section><section><p className="bf-kicker">BACKUP ȘI RECUPERARE</p><h2>Protejează registrul local</h2><p>Backup-ul este un fișier local JSON. Nu este trimis automat în rețea și poate fi importat pe un alt dispozitiv.</p><div className="bf-backup-actions"><button onClick={() => downloadBackup(data)}><Download size={16} /> Exportă backup</button><label className="bf-file-button"><Upload size={16} /> Importă backup<input type="file" accept="application/json,.json" onChange={importBackup} /></label></div></section><section className="bf-danger"><p className="bf-kicker">RESETARE</p><h2>Începe curat pe acest dispozitiv</h2><p>Șterge numai datele locale. O copie sincronizată sau exportată nu este afectată.</p><button onClick={onReset}><Trash2 size={16} /> Resetează datele locale</button></section></div>;
}

function SyncPanel({ data, onChange }: { data: AppData; onChange: (value: AppData) => void }) {
  const [token, setToken] = useState(""); const [password, setPassword] = useState(""); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const [connected, setConnected] = useState(false); const [lastSync, setLastSync] = useState(""); const [journal, setJournal] = useState<SyncJournalEntry[]>(readSyncJournal); const shaRef = useRef<string | undefined>(undefined); const dataRef = useRef(data); dataRef.current = data;
  const appendJournal = (entry: Omit<SyncJournalEntry, "id">) => { setJournal((current) => { const next = [{ ...entry, id: newId("sync-log") }, ...current].slice(0, 40); writeSyncJournal(next); return next; }); };
  const owner = "Balty1991"; const repo = "buget-familie-date"; const path = "family-sync.enc.json";
  const check = () => { if (!token.trim()) throw new Error("Introdu un token GitHub limitat la repo-ul privat de date."); if (password.length < 12) throw new Error("Parola de criptare trebuie să aibă cel puțin 12 caractere."); };
  const portable = (value: AppData) => ({ ...value, receipts: value.receipts.map(({ imageData: _one, imageData2: _two, imageKeys: _keys, ...rest }) => rest) });
  const retainLocalReceiptImages = (value: AppData): AppData => ({ ...value, receipts: value.receipts.map((receipt) => { const local = dataRef.current.receipts.find((item) => item.id === receipt.id); return { ...receipt, imageData: local?.imageData, imageData2: local?.imageData2, imageKeys: local?.imageKeys }; }) });
  const syncNow = async (announce = true): Promise<boolean> => {
    check(); setBusy(true);
    try {
      let remote = await getRemotePackage({ token, owner, repo, path });
      let remoteData = remote ? normalizeAppData(await decryptFamilyData(remote.envelope, password)) : createEmptyAppData();
      let merged = retainLocalReceiptImages(remote ? mergeFamilyData(dataRef.current, remoteData) : dataRef.current);
      if (remote && JSON.stringify(portable(merged)) === JSON.stringify(portable(remoteData))) { shaRef.current = remote.sha; onChange(merged); setLastSync(new Date().toISOString()); if (announce) setNotice("Familia era deja actualizată. Nu a fost creat un commit nou."); return true; }
      let conflictResolved = false;
      const conflictId = newId("sync-conflict");
      try { const envelope = await encryptFamilyData(portable(merged), password); shaRef.current = await saveRemotePackage({ token, owner, repo, path, envelope, sha: remote?.sha }); }
      catch (error) {
        if (!(error instanceof GitHubSyncError) || error.kind !== "conflict") throw error;
        appendJournal({ conflictId, createdAt: new Date().toISOString(), status: "detected", message: "GitHub a raportat o versiune concurentă a registrului.", action: "Copia locală și cea remote au fost reunite înainte de reîncercare." });
        remote = await getRemotePackage({ token, owner, repo, path });
        if (!remote) throw new Error("Copia de familie s-a schimbat înainte de reunire. Apasă din nou Sincronizează acum.");
        remoteData = normalizeAppData(await decryptFamilyData(remote.envelope, password));
        merged = retainLocalReceiptImages(mergeFamilyData(dataRef.current, remoteData));
        const envelope = await encryptFamilyData(portable(merged), password);
        shaRef.current = await saveRemotePackage({ token, owner, repo, path, envelope, sha: remote.sha });
        conflictResolved = true;
        appendJournal({ conflictId, createdAt: new Date().toISOString(), status: "resolved", message: "Conflictul a fost reunit și încărcat criptat.", action: "Merge-ul local și remote a fost publicat în repo-ul privat." });
      }
      onChange(merged); setLastSync(new Date().toISOString()); if (announce) setNotice(conflictResolved ? "Două actualizări au ajuns în același timp; le-am reunit și criptat. Verifică planul dacă a fost editat pe ambele telefoane." : "Familia este actualizată. Modificările au fost reunite și criptate."); return true;
    } catch (error) { setNotice(error instanceof Error ? error.message : "Nu s-a putut actualiza familia."); return false; } finally { setBusy(false); }
  };
  const connect = async () => { if (!token.trim() || password.length < 12) return setNotice("Introdu tokenul repo-ului privat și o parolă de cel puțin 12 caractere."); if (await syncNow(false)) { setConnected(true); setNotice("Sesiunea familiei este activă. Verificăm actualizări la aproximativ 30 de secunde cât aplicația rămâne deschisă."); } };
  const pull = async () => { try { check(); setBusy(true); const remote = await getRemotePackage({ token, owner, repo, path }); if (!remote) return setNotice("Nu există încă o copie în repo-ul privat."); const restored = normalizeAppData(await decryptFamilyData(remote.envelope, password)); onChange(retainLocalReceiptImages(mergeFamilyData(dataRef.current, restored))); shaRef.current = remote.sha; setLastSync(new Date().toISOString()); setNotice("Actualizările familiei au fost reunite local, fără a șterge intrările acestei sesiuni. Atinge Sincronizează acum dacă ai avut modificări locale."); } catch (error) { setNotice(error instanceof Error ? error.message : "Nu s-a putut descărca copia."); } finally { setBusy(false); } };
  useEffect(() => { if (!connected) return; const interval = window.setInterval(() => { void syncNow(false); }, 30_000); return () => window.clearInterval(interval); }, [connected, token, password]);
  return <div className="bf-sync"><div className="bf-sync-hero"><Users size={25} /><p className="bf-kicker">FAMILIE CONECTATĂ</p><h2>{connected ? "Sesiunea familiei este activă." : "Sincronizare criptată între telefoane."}</h2><p>În repo-ul privat ajunge doar un pachet AES-GCM. Pozele bonurilor și parola rămân pe telefon.</p></div><section className="bf-sync-session"><p className="bf-kicker">{connected ? "CONECTAT" : "CONECTEAZĂ FAMILIA"}</p>{connected ? <><p><b>Actualizare prudentă la aproximativ 30 secunde</b><br />Sesiunea funcționează cât aplicația este deschisă. Tokenul rămâne doar în memorie.</p><div className="bf-sync-actions"><button className="bf-secondary" disabled={busy} onClick={() => void pull()}><Download size={16} /> Verifică acum</button><button className="bf-primary" disabled={busy} onClick={() => void syncNow()}><Cloud size={16} /> Sincronizează acum</button></div><button className="bf-link-button" onClick={() => { setConnected(false); setToken(""); setPassword(""); setNotice("Sesiunea a fost închisă pe acest telefon."); }}>Închide sesiunea acestui telefon</button></> : <><Field label="Token GitHub limitat"><input type="password" value={token} onChange={(event) => setToken(event.target.value)} placeholder="github_pat_..." autoComplete="off" /></Field><Field label="Parola de criptare a familiei"><input type="password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="minimum 12 caractere" autoComplete="new-password" /></Field><p className="bf-helper">Pe fiecare telefon se folosește un token fine-grained separat, cu <b>Contents: Read and write</b> doar pentru repo-ul privat <b>{repo}</b>. Tokenul și parola nu se salvează.</p><button className="bf-primary full" disabled={busy} onClick={() => void connect()}><Users size={17} /> Conectează acest telefon</button></>}</section>{lastSync && <p className="bf-helper">Ultima actualizare: {new Intl.DateTimeFormat("ro-RO", { hour: "2-digit", minute: "2-digit", second: "2-digit" }).format(new Date(lastSync))}</p>}{notice && <p className="bf-notice" role="status"><Check size={15} /> {notice}</p>}<section className="bf-sync-journal" aria-labelledby="sync-journal-title"><div className="bf-sync-journal-heading"><div><p className="bf-kicker">ISTORIC DE CONFLICTE</p><h3 id="sync-journal-title">Ce s-a întâmplat la sincronizare</h3></div>{journal.length > 0 && <button className="bf-link-button" onClick={() => { setJournal([]); writeSyncJournal([]); }}>Curăță istoricul</button>}</div>{journal.length ? <div className="bf-sync-journal-list">{journal.map((entry) => <article key={entry.id} className={`bf-sync-journal-entry ${entry.status}`}><div className="bf-sync-journal-icon" aria-hidden="true">{entry.status === "resolved" ? <Check size={15} /> : entry.status === "failed" ? <X size={15} /> : <RotateCcw size={15} />}</div><div><strong>{entry.status === "resolved" ? "Conflict rezolvat" : entry.status === "failed" ? "Conflict nerezolvat" : "Conflict detectat"}</strong><p>{entry.message}</p><small>{new Intl.DateTimeFormat("ro-RO", { dateStyle: "short", timeStyle: "short" }).format(new Date(entry.createdAt))} · {entry.action}</small>{entry.status !== "resolved" && <button className="bf-link-button" disabled={!connected || busy} onClick={() => void syncNow()}>Reia sincronizarea</button>}</div></article>)}</div> : <p className="bf-helper">Nu există conflicte înregistrate pe acest dispozitiv. Dacă două telefoane modifică registrul în același timp, aici vei vedea ce a fost detectat și cum a fost rezolvat.</p>}</section></div>;
}

function FamilyGuide() { return <div className="bf-guide"><section className="bf-guide-hero"><BookOpen size={25} /><p className="bf-kicker">MANUAL RAPID</p><h2>Doar tu sau împreună.</h2><p>Poți urmări banii proprii de la prima deschidere. Membrii și conectarea telefoanelor sunt opționale.</p></section><section><p className="bf-kicker">1. PORNEȘTE CU TINE</p><h3>Configurează profilul și banii reali</h3><p>În <b>Setări familie</b>, păstrează un singur membru pentru monitorizare personală sau adaugă mai mulți membri când aveți un buget comun. Configurează sursele și soldurile inițiale, apoi creează planul până la următorul venit.</p></section><section><p className="bf-kicker">2. CONECTEAZĂ OPȚIONAL</p><h3>Folosește repo-ul privat, nu repo-ul aplicației</h3><p>Dacă vrei același registru pe mai multe telefoane, administratorul creează tokenuri fine-grained distincte cu <b>Contents: Read and write</b> numai pentru <b>buget-familie-date</b>. În <b>Mai mult → Sincronizare</b>, fiecare telefon folosește tokenul propriu și aceeași parolă de grup.</p></section><section><p className="bf-kicker">3. LUCREAZĂ ZILNIC</p><h3>Înregistrează, verifică, decide</h3><p>Adaugă mișcările la momentul plății. Pentru cumpărături mixte, un bon poate avea două poze și mai multe categorii. Verifică zilnic punctul de decizie și confirmă scadențele când sunt plătite.</p></section><section><p className="bf-kicker">4. PROTEJEAZĂ DATELE</p><h3>Nu trimite parole sau tokenuri</h3><p>Tokenul și parola nu sunt salvate de aplicație. Nu le pune în conversații, bonuri sau capturi de ecran. Dacă un telefon se pierde, revocă tokenul acelui telefon în GitHub și creează unul nou.</p></section></div>; }

/** Atelierul Financiar 3.0 — Analiza este o destinație de lucru, cu rapoarte și asistent separat încărcate la cerere. */
function InsightsView({ data }: { data: AppData }) {
  const [panel, setPanel] = useState<"reports" | "assistant">("reports");
  return <div className="bf-page bf-insights-workspace"><header className="bf-insights-header"><div><p className="bf-kicker">ANALIZĂ FINANCIARĂ</p><h1>Înțelege <em>schimbarea.</em></h1><p>Compară lunile, verifică bilanțul și cere o explicație locală a datelor introduse.</p></div><span><LayoutDashboard size={25} /></span></header><div className="bf-insights-switch" role="tablist" aria-label="Tip analiză"><button role="tab" aria-selected={panel === "reports"} className={panel === "reports" ? "active" : ""} onClick={() => setPanel("reports")}><LayoutDashboard size={16} /> Istoric</button><button role="tab" aria-selected={panel === "assistant"} className={panel === "assistant" ? "active" : ""} onClick={() => setPanel("assistant")}><Bot size={16} /> Asistent</button></div>{panel === "reports" ? <Suspense fallback={<div className="bf-lazy-panel">Pregătim analiza…</div>}><ReportsPanel data={data} /></Suspense> : <Suspense fallback={<div className="bf-lazy-panel">Pregătim asistentul…</div>}><AdvisorPanel data={data} /></Suspense>}</div>;
}

